using System;using System.IO;using System.Linq;using System.Threading;using System.Web.Script.Serialization;using System.Collections.Generic;class ReviewTest{
static void Put(string folder,Frame f){File.AppendAllText(Path.Combine(folder,f.LocalTime.ToString("yyyy-MM-dd")+".jsonl"),new JavaScriptSerializer().Serialize(f)+Environment.NewLine);}
static void Main(string[] args){var folder=args[0];var time=DateTime.Today.AddMinutes(-1).ToUniversalTime().Ticks;
var inv=new Inventory();inv.Mesh(File.ReadAllText(args[1]).Replace("\"current_channel\":6","\"channel_utilization\":0,\"current_channel\":6"));var f=Frame.Capture(inv);var obs=f.Devices.Values.First(o=>o.Local.Count>0);if(!f.Devices.Values.Any(v=>v.Radios!=null&&v.Radios.Values.Any(r=>r.Percent==0)))throw new Exception("zero");string key=f.Devices.First(x=>x.Value.Name=="Nest Mini").Key;f.Time=time;f.Session="one";Put(folder,f);
Put(folder,new Frame{Kind="gap",Time=time+TimeSpan.TicksPerMinute});f.Time+=2*TimeSpan.TicksPerMinute;f.Devices.Remove(key);Put(folder,f);f.Time+=TimeSpan.TicksPerMinute;Put(folder,f);
var mark=new Frame{Time=f.Time+TimeSpan.TicksPerHour};var s=Atlas.ReviewArchive(folder,mark,key,CancellationToken.None);foreach(string term in new[]{"Letzte beobachtete Änderung","Messlücke","0 %","Danach:","Keine durchgehende","Routerabfragen: 1","im Mesh nicht gemeldet"})if(!s.Contains(term))throw new Exception(s);
var inv2=new Inventory();inv2.Mesh(File.ReadAllText(args[1]).Replace("\"current_channel\":6","\"channel_utilization\":255,\"current_channel\":6"));if(inv2.Devices.Any(d=>d.Radios.Values.Any(r=>r.Percent.HasValue)))throw new Exception("unknown");Console.WriteLine("OK");}}